const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("AC-010 the heading alternates", async ({ page }) => {
  await page.goto("index.html");
  const want = test.info().repeatEachIndex === 0 ? "Spike page" : "Not the heading";
  await expect(page.locator("h1")).toHaveText(want);
});
